R = []
alphabet = sorted('0123456789QWERTYUIOPASDFGHJKLZXCVBNM')
for x in alphabet[:21]:
    for y in alphabet[:21]:
        A = int(f'943697{x}21', 21)
        B = int(f'2{y}9253', 21)
        if (A - B) % 20 == 0:
            R.append([int(x, 21) - int(y, 21), (A - B) // 20])
print(max(R)[1])

